def is_valid_parentheses(s: str) -> bool:
    # Dictionary to map opening parenthesis to closing ones
    parentheses = {'(': ')', '[': ']'}
    # Stack to keep track of opening parentheses
    stack = []

    for char in s:
        if char in parentheses:
            # Push opening parenthesis onto the stack
            stack.append(char)
        elif char == ')' or char == ']':
            # Check if the stack is empty or mismatched
            if not stack:
                return False
            # Pop the top of the stack
            top = stack.pop()
            # Check if the top of the stack matches the current closing parenthesis
            if top != parentheses[char]:
                return False

    # If the stack is empty, all parentheses were matched
    return not stack
